    "overview": "Embarking aboard Saroche near Dijon, cruise the quintessentially French region of Burgundy, pausing for food and wine tastings in the magical vineyards of the Côte d’Or and visits to quaint hamlets and medieval villages along the way.",
    "highlights": [
      "Sleeps six guests in three queen/twin cabins, each outward facing with en suite bathroom",
      "Gather for meals in the outdoor dining area with firepit",
      "Crew of four ensures your comfort onboard",
      "Borrow one of the provided bicycles for a relaxing ride along the towpath"
    ],
    "itinerary": [
      {
        "day": "Day 1",
        "title": "Sunday | Paris to Escommes",
        "text": "Meet in Paris. Then, embark on Saroche from its mooring in Vandières.\nMeals: Dinner"
      },
      {
        "day": "Day 1.1",
        "title": "Transfer: Saint-Léger-sur-Dheune to Santenay",
        "text": ""
      },
      {
        "day": "Day 2",
        "title": "Monday | Escommes to Châteauneuf-en-Auxois",
        "text": "Travel down a flight of locks to Châteauneuf-en-Auxois. After lunch, visit the wine-producing village of Saint Roman and an organic artisanal goat cheese producer.\nMeals: Breakfast, Lunch, Dinner"
      },
      {
        "day": "Day 2.1",
        "title": "Transfer: Santenay to Rully",
        "text": ""
      },
      {
        "day": "Day 3",
        "title": "Tuesday | Châteauneuf-en-Auxois to Le Pont d’Ouche",
        "text": "After visiting Châteauneuf-en-Auxois, travel downstream to Pont d’Ouche through 10 locks, maybe traversing the towpaths by foot or bike.\nMeals: Breakfast, Lunch, Dinner"
      },
      {
        "day": "Day 4",
        "title": "Wednesday | Le Pont d’Ouche to Beaune",
        "text": "Today visit the capital of Burgundy wine production, Beaune, known for both the wine and traditional tiled roofs. After visiting the Hospice du Beaune, have a comprehensive wine tasting in the labyrinth cellars.\nMeals: Breakfast, Lunch, Dinner"
      },
      {
        "day": "Day 4.1",
        "title": "Transfer: Rully to Fragnes-la-Loyere",
        "text": ""
      },
      {
        "day": "Day 5",
        "title": "Thursday | Beaune to La Bussière-sur-Ouche",
        "text": "After a leisurely sailing in the morning and lunch onboard, the afternoon visits include a special wine tasting.\nMeals: Breakfast, Lunch, Dinner"
      },
      {
        "day": "Day 5.1",
        "title": "Transfer: Fragnes-la-Loyere to Chalon-sur-Saône",
        "text": ""
      },
      {
        "day": "Day 6",
        "title": "Friday | La Bussière-sur-Ouche to Gissey-sur-Ouche",
        "text": "Today is market day in Dijon with visits to Dijon’s old town, some of the best markets in France, and specialty shops and cafes. The afternoon visit takes you to a small village where the barge is moored.\nMeals: Breakfast, Lunch, Dinner"
      },
      {
        "day": "Day 6.1",
        "title": "Transfer: Chalon-sur-Saône to null",
        "text": ""
      },
      {
        "day": "Day 7",
        "title": "Saturday | Gissey-sur-Ouche to Paris",
        "text": "Disembark in Gissey-sur-Ouche and return to Paris.\nMeals: Breakfast"
      }
    ],
