        "title": "Mar 3 | Malta – A Journey-Ending Celebration",
        "text": "Step into the past for an exclusive celebration on an island outpost in the Mediterranean\nYour group reunites in Nairobi as you board your private jet for Malta. Celebrate the end of your journey with a private after-hours visit to St. John’s Co-Cathedral, where its austere exterior contrasts dramatically with a richly ornate High Baroque interior. Then experience one of Malta’s oldest traditions — the festa, or village feast — where one of Malta’s oldest and most respected marching bands leads you through the streets for a specially curated festival of food, drinks, music and traditional entertainment, an unforgettable window into Maltese community and culture.\nMeals: Breakfast, Lunch, Dinner"
