    "overview": "Named after one of the stars in the Seven Sisters constellation, Maia captures the style and culture of Eastern influences in a unique Seychelles setting. Thirty secluded private pool villas are surrounded by lush tropical gardens and pristine beaches, each with their own infinity pool, undisturbed ocean views and a Villa Host on hand to ensure a seamless stay. This sustainability-focused resort has curated unique experiences to help you discover the incredible natural life on the islands of Praslin and La Digue, from a helicopter ride to the uninhabited Aride Bird Reserve Island to a boat tour to explore the unspoiled reefs.",
