      "The house reef teeming with marine life, including manta rays on the west side of the island",
      "A mix of excursions offering that includes voyaging on Nooma, a traditional handcrafted Maldivian sailing dhoni, or a cruise on Serenity, a modern luxury motor yacht",
      "A choice of three resort restaurants, as well as private dining options including a dinner cruise for two aboard a dhoni",
