    "overview": "A whitewashed chalet perched high on a cliff, this elegant adults-focused escape offers panoramic ocean views and a design that fuses contemporary amenities with the charm of 20th century history. A member of the prestigious Relais & Châteaux, this 5-star boutique hotel in Praia da Rocha takes particular pride in its culinary offering, with the star of the show being VISTA, the Michelin-starred restaurant led by Chef João Oliveira. The 38 rooms are divided across three different buildings: the mansion, which has 11 historical rooms; Bela Vista Jardim, with 20 rooms, all with a terrace or garden and a sea view; and Casa Azul, with 7 rooms, decorated in bright colours that echo its name. For those looking to unwind, head to the Spa da L’Occitane, which has 5 treatment rooms, a sauna, steam bath and plunge pool.",
