    "overview": "Perched above the picturesque fishing town of Ammoudi, Canaves Oia Epitome holds the enviable position of being the only property on the island to offer guests both sea and sunset views from their room. The 53 accommodations, which range from elegant suites to the grand five-bedroom villa, embrace traditional Cycladic architecture, combined with all the modern comforts. In addition to the sprawling ocean views, each comes with either a plunge or full pool and private outdoor space–the Honeymoon Suite is a particularly good option for newlyweds. Around the property, you’ll find the infinity pool, relaxing spa and two elegant restaurants that make the most of the hotel’s impressive position. If you want to get off-site, the hotel can arrange any number of experiences, from olive oil tastings to sailing excursions.",
