    "overview": "For one of the fastest ways to get from tarmac touchdown to lapping lagoon, the original Four Seasons hotel in the Maldives is hard to beat. A 25-minute speedboat ride from the airport delivers you to its string of overwater villas in the jewel-toned waters of the North Malé atoll, where white-sand paths are lined with fragrant frangipani and bursts of bougainvillea. With soaring thatched ceilings and woven screens, traditional-village-inspired villas root guests in their surroundings. Further immersion happens in the spa, where massage beds are set on glass floors for marine-life spotting while you unwind. On the flip side, six quality surf breaks and shipwreck dives keep adrenalin levels topped up – Kuda Huraa has a Tropicsurf school and annual surf championship which has brought pros including Kelly Slater to the island. There’s a tennis academy too. Not your average Maldives escape.",
    "highlights": [
      "Tandoor tapas at Indian restaurant Baraabaru; Maldivian barbeque night at Kandu Grill.",
      "A finely tuned family offering for inspiring young environmentalists through turtle monitoring and coral-reef building.",
      "Sailing on a traditional dhoni to the spa for ocean-inspired treatments that swap heated stones for warmed seashells.",
      "Water villas angled for either sunrise or sunset, each with an infinity pool for a dip facing daybreak or dusky skies."
    ],
