    "overview": "Cocooned by a private sanctuary on the east coast of Mauritius, the Four Seasons at Anahita embraces endless views of blue waters against a backdrop of green-blanketed mountains. Here, you can enjoy an oceanfront finish on the Ernie Els-designed 18-hole championship golf course, locally inspired treatments in the overwater spa and your own spacious villa that effortlessly integrates with the natural surroundings. For extra privacy, there are the Lagoon Pool Villas located on the private Ile aux Chats around the turquoise lagoon, and if you are travelling as a family – or are a couple looking for more space – the Two and Three Bedroom Residence Villas include a fully equipped kitchen, living area, dining room and study.",
