    "overview": "An artistic resort located on Raa Atoll in the northern Maldives, JOALI comprises uniquely furnished water and beachfront villas, each with a private infinity pool, superb entertainment facilities and a dedicated butler service. Framed by white beaches and azure waters, the resort is focused on paying homage to creativity and craftsmanship, with an island-wise series of interactive collections and installations , designed to captivate art connoisseurs and patrons alike.",
