    "overview": "Here’s a crowd-pleaser of a five-star resort spread over two islands in the Dhaalu Atoll – one called Play (for families and thrill-seekers) and one called Chill (for romantics). The islands are linked by a bridge and span one and a half miles of banyan trees, coconut palms and shaded paths for pootling along on your complimentary bicycle. The Indian Ocean’s biggest kids’ club has imaginative endeavours for all ages from one- to 12-year-olds, while the resort’s 10 dining experiences range from an underwater Nikkei restaurant to teppanyaki soundtracked by birdsong in the treetops at Nest. DJs and jazz duos keep the tempo raised in the evenings and ancient Ayurvedic treatments at Drift Spa dial it all down again.",
