    "overview": "Spread over the largest island in the North Malé Atol, One& Only Reithi Rah is a decadently luxurious escape framed by 12 pristine beaches and the Indian Ocean’s crystalline waters. An idyllic hideaway for families and couples alike, each of the beach or water-front villas offer seclusion and plenty of space to unwind and recharge. For those who like to keep busy, there’s a variety of experiences to explore - go diving with a PADI-certified instructor, learn about the resort’s sea turtle conservation project with a marine biologist before setting in search of the hawksbill turtles, or simply jump on one of the bikes to wind your way around the resort’s 44 hectares at your leisure. If relaxation is on the agenda, spend your days lounging on one of the many beaches, take a dip in the sublime infinity pool or book one of the treatments at the waterfront spa.",
