    "overview": "The arrival of this chic seaside retreat signalled the revival of Glyfada, the city’s weekend coastal escape better known as the Athens Riviera – in its 1960s heyday a summer playground for Jackie O and Brigitte B. One&Only Aesthesis updates the glamour for a new generation. Set on its own gated peninsula within 21 hectares of pine forest, the hotel has 100-odd rooms and low-rise wood-and-glass bungalows (including some fully accessible), in gardens or beside the sea. Strong eco credentials include the protection of forested land on the peninsula and sensitive relandscaping of a stretch of coast that was ravaged by development in previous decades. The food here is superb; we particularly love the tapas joint helmed by a Michelin-star-winning chef, and waterfront Manko, which transforms into a poolside beach club with live DJs in the evenings. There’s also a Guerlain spa, a kids’ club for ages 4-11, tennis and loads of watersports. More than enough to keep you here day and night, but it’s also the perfect spot for a beach-and-city break, with Athens a half-hour drive away.",
