    "overview": "When opened in the 1970s on its own private peninsula, it really was the one and only luxury resort in Mauritius. It is testament to its team and its vision that, 50 years later, One&Only Le Saint Géran is still the glamorous go-to for palm-fringed beaches, dreamy pools (we love the Palm Grove’s swim-up bar) and days spent deep-sea fishing or stand-up paddleboarding on the reef-protected waters of the east coast. More recently, the first Guerlain spa in Mauritius has upped the hotel’s wellness game, and brand-new beach club Riva has DJs, private poolside cabanas and chic Italian-inspired design. Plus, a new collection of Private Homes are ideal for families and groups of friends, each with up to six bedrooms.",
