    "overview": "Positioned on the picturesque Le Morne peninsula on the island's South-western tip, the Paradis Beachcomber Golf Resort & Spa is a spacious haven for sports lovers and families alike. In addition to the white sand beaches just steps from every room, gorgeous lagoon and extensive water sports for adults and children, golf lovers will particularly appreciate the access to two championship golf courses, which is also home to the Golf Academy where pros are on hand to iron out your weaknesses with the aid of sophisticated computer software.",
