    "overview": "Since its opening in 1979, Puente Romano Marbella has provided a prestigious and luxurious getaway. Located in the heart of Marbella's Golden Mile, only 2 miles from bustling Puerto Banus, the resort echoes the charm and character of an Andalusian beach village; its 162 suites, each with its own private terrace, is decorated in a simple and elegant Mediterranean style, and there are three villas for those seeking extra privacy. All tastes are catered for with 20 superb restaurants and bars with a variety of choices from all over the world, including an outpost of Cipriani and Nobu. With a Six Senses Spa, a private beach with water sports, world famous tennis club with pros on hand to provide lessons and three swimming pools, the property is a perfect choice for those looking to relax and unwind.",
