    "overview": "An iconic resort dotted across 34 hectares and 5 pristine beaches on Mauritius’ beautiful east coast, Shangri-La’s Le Touessrok Resort & Spa comprises a collection of 189 rooms and suites plus three exclusive villas. For the most contemporary styled room, step over the footbridge to Frangipani Island, where Junior Suites offer uninterrupted ocean views, state of the art technology, and direct beach access. For the utmost privacy and luxury, the private three-bedroom Villas are secluded at the end of the beach, with a private infinity pool, 24/7 butler service and access to a private chef. During the day, children and teens can stay entertained at T-Club, while grown-ups can explore the wide array of experience offerings, from the championship golf course to the private island complete with beach cabanas and spa services",
