    "overview": "Located on the private coral-fringed island Félicité, this resort comprises 32 spacious villas ranging from one- to four-bedroom residences. Dotted between the beach and the surrounding lush tropical vegetation, each villa comes with its own pool and striking panoramic views of the Indian Ocean. A paradise for divers and snorkelers, the clear waters surrounding Félicité are ideal for spotting marine life. If you wish to explore, you can take out a kayak or stand-up paddleboard around the island, and for those who want to travel further, you can go island hopping by boat stopping at exclusive beaches.",
