    "overview": "Set on the mythic island of Crete, St Nicolas Bay is a sumptuous escape designed to cater to families, couples, and everyone in between. Conveniently located on the eastern coast, close to many of the island’s most renowned attractions, the expansive resort offers a mix of accommodations to suit every type of traveller, including intimate ocean-view suites and expansive private villas big enough to house the entire family. Across the property, you’ll find the Poseidon Spa, complete with hammam and island-inspired treatment rooms, a large pool and access to the private beach, as well as the hotel’s own art gallery, Argonaftis. While there’s plenty on site to keep everyone entertained, the resort also offers plenty of adventures, including guided excursions to some of Crete’s most significant sites and watersports arranged by their own Water Sports Center.",
