    "overview": "If Mauritius is the Indian Ocean island for action and adventure, then Sunlife’s Sugar Beach resort is its ultimate playground. It is set on one of the finest beaches in Mauritius, with powdery white sand and warm turquoise shallows teeming with fish. Sandy footpaths wind from suites through acres of lush, green gardens, and there is a terrific variety of things to do, places to hang out, eat and drink (there are seven restaurants) and activities for all ages – including four pools, tennis courts, a whole raft of free watersports, action-packed kids and teens clubs and creative workshops for adults, as well as access to two of the world’s most stunning golf courses, Tamarina and Ile aux Cerfs. There’s even a microbrewery and a music studio. On the island’s west coast, it is also well-placed for exploratory day trips to the capital of Port Louis and Black River Gorges National Park – and for sunset drinks overlooking the Indian Ocean.",
