      "The Rainforest Spa at the foot of the Petit Piton, where treatments harness the natural ingredients from volcanic springs and fertile cocoa plantations and treatment rooms are treehouses",
      "Eight restaurants and bars spanning beachfront decks, formal dining rooms and Cocoa Mill, the resort’s chocolate boutique",
