    "overview": "A discreet, “if you know, you know” resort tucked on one of the west coast’s sandy beaches, The Sandpiper is one of those charming escapes you can’t wait to visit again. Blending island ease with sumptuous elegance, the 47 rooms and suites offer garden or ocean views, each with their own outdoor space where you can enjoy the bougainvillea-scented air. Amongst the one- and two-bedroom suites, there is the sought after Curlew, an oceanfront escape with a private terrace, personal plunge pool and unbeatable sea views, and tree-top suites with private pools. Around the property, guests will find two pools, beautiful gardens, two tennis courts and, of course, the private beach. For the more active-minded, The Sandpiper offers access to two nearby golf courses, as well as plenty of watersports.",
