      "Internal Air Included (Economy Class, £925 value) Nairobi/Maasai Mara/Nairobi/Ol Pejeta/Nairobi",
      "Internal Air Included (Economy Class, AU$1,835 value) Nairobi/Maasai Mara/Nairobi/Ol Pejeta/Nairobi",
