    "faqs": [
      {
        "q": "Minimum Age",
        "a": "Minimum age is 10 years old"
      },
      {
        "q": "A&K Safari Duffel",
        "a": "Each guest will receive an A&K safari duffel"
      },
      {
        "q": "First Group Event",
        "a": "Welcome briefing at 8:30 a.m. on Day 2"
      },
      {
        "q": "Last Group Event",
        "a": "Lunch at 1:30 p.m. on Day 8"
      },
      {
        "q": "Guaranteed Departures",
        "a": "Departures are guaranteed to operate with a minimum of 2 guests"
      },
      {
        "q": "General Requirements",
        "a": "Your passport needs to be valid for at least six (6) months after your journey ends and should have a minimum of two (2) blank visa pages for entry and exit stamps for each country visited on your journey.\nOur partner VisaCentral offers easy, efficient U.S. passport and visa processing. Visit them online at visacentral.com or call 844 823 1224 and reference A&K's account number 73001. Service fees apply. Citizens of other countries should contact the appropriate consular office for entry requirements pertaining to their journey."
      },
      {
        "q": "Passport Copy Required at time of Booking",
        "a": "Passport copies are required at the time of booking for all guests to confirm included services. Please sign in or register to your personalized A&K account to enter passport details and upload a copy in the Guest Documentation section."
      },
      {
        "q": "Visa Requirements",
        "a": "A tourist visa is required for U.S. or Canadian passport holders for entry into Tanzania and A&K recommends an electronic visa (eVisa). To apply, visit visa.immigration.go.tz. U.S. citizens must apply for a multiple-entry visa, valid for one year. Canadian citizens may obtain a single-entry eVisa (ordinary visa), valid for three months. Apply at least 60 days prior to your arrival date. The application will ask you for host details. Please use:\nAbercrombie & Kent Tanzania\nNjiro Hill P.O. Box 427\nArusha, Tanzania\nTelephone Number: +255 739 50 8346\nHost Email: info@abercrombiekent.co.tz.\nA visa can also be obtained on arrival in Tanzania, however, the visa on arrival process requires applicants to stand in several different lines with wait times of two hours or longer."
      },
      {
        "q": "Additional Entry Requirements",
        "a": "Travellers to Zanzibar: In addition to a Tanzanian visa, the archipelago of Zanzibar requires visitors to show proof of mandatory Inbound Travel Insurance. Insurance must be purchased from the Zanzibar Insurance Corporation (ZIC) at https://inbound.visitzanzibar.go.tz/ and is valid up to 92 days from your arrival date in Zanzibar. Travel insurance policies issued in USA or Canada are not accepted for entry. Upon payment, you will receive a QR code to present prior to boarding your departure flight and on arrival in Zanzibar."
      },
      {
        "q": "Traveller's Health",
        "a": "We recommend you check the Smartraveller website for Australian passport holders https://www.smartraveller.gov.au/ and Safe Travel for New Zealand passport holders https://www.safetravel.govt.nz/ for the latest on required and recommended vaccines and health requirements for your destination."
      },
      {
        "q": "Malaria Prevention",
        "a": "You will be travelling to areas of malaria transmission. We strongly advise that you speak with your doctor or travel clinic regarding your itinerary, individual risk assessment and options for mosquito bite prevention, and antimalarial drugs. We recommend filling any prescriptions before you depart."
      },
      {
        "q": "Yellow Fever Vaccination: If Arriving from Endemic Country",
        "a": "A yellow fever vaccination, administered at least 10 days prior to your arrival, is only required for this destination if you are arriving from, or have transited through, a yellow fever-endemic area in South America or Africa. The CDC and WHO each provide a current list of all affected countries. Please be sure to carry the International Certificate of Vaccination provided by your physician, as you may be denied entry without it. If your physician advises against receiving the vaccination, they can provide you with the necessary documentation."
      },
      {
        "q": "Register Your Journey",
        "a": "Be sure to register with your nearest embassy or consulate for the destinations included in your journey. U.S. citizens can register through STEP, the Smart Traveler Enrollment Program (step.state.gov/step). Canadian citizens can enroll in Registration of Canadians Abroad at Registration of Canadians Abroad."
      },
      {
        "q": "Country Specific Information",
        "a": "Abercrombie & Kent strongly advises all travellers to be aware of the most recent travel information, special considerations and advisories to the country you are visiting.\nFor Australian passport holders, please visit Smartraveller; and for New Zealand passport holders, please visit SafeTravel."
      }
    ],
