        "title": "South Luangwa National Park – Untamed Beauty",
        "text": "Meet your guide again for a bush walk to Mchenja, beside the Luangwa River. Between safari activities, a pool overlooking the river offers a peaceful retreat. Guided walks and night drives showcase the park’s rich wildlife, including big cats and seasonal sightings of carmine bee-eaters. The rest of the day is yours to enjoy game viewing at your leisure.\nMeals: Breakfast, Lunch, Dinner"
